sp_AtualizarStatusPedido	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_AtualizarStatusPedido`(\n\n    IN p_idPedido        INT,\n\n    IN p_statusPedido_id INT,\n\n    IN p_idUsuario       INT,\n\n    IN p_observacao      VARCHAR(300)\n\n)\nBEGIN\n\n    DECLARE v_statusAtual INT;\n\n\n\n    SELECT statusPedido_id INTO v_statusAtual\n\n    FROM Pedido WHERE idPedido = p_idPedido;\n\n\n\n    IF p_statusPedido_id = 6 AND v_statusAtual != 6 THEN\n\n        CALL sp_DevolverEstoquePedido(p_idPedido, p_idUsuario);\n\n    END IF;\n\n\n\n    UPDATE Pedido\n\n    SET statusPedido_id = p_statusPedido_id\n\n    WHERE idPedido = p_idPedido;\n\n\n\n    IF p_idUsuario IS NOT NULL THEN\n\n        INSERT INTO PedidoStatusHistorico (idPedido, statusPedido_id, idUsuario, dthAlteracao, observacao)\n\n        VALUES (p_idPedido, p_statusPedido_id, p_idUsuario, CONVERT_TZ(NOW(), '+00:00', '-03:00'), p_observacao);\n\n    END IF;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
